// Package notices holds the license texts of Oganesson and of the
// third-party software linked or embedded into og. og prints them with
// `og licenses`, packaged app binaries and ejected modules with -licenses,
// followed by the app's own (AppFile, written by og build).
//
// THIRD_PARTY_NOTICES.txt is generated by scripts/collect-notices.sh and
// checked in; CI fails when it is stale.
package notices

import (
	_ "embed"
	"errors"
	"io"
	"io/fs"
)

//go:generate sh ../../scripts/collect-notices.sh THIRD_PARTY_NOTICES.txt

// Text is the full notice text.
//
//go:embed THIRD_PARTY_NOTICES.txt
var Text string

// AppFile is the payload file holding the licenses of the npm packages
// bundled into the app (internal/licenses).
const AppFile = "THIRD_PARTY_NOTICES.txt"

// Write writes Text, then the app's AppFile when app has one.
func Write(w io.Writer, app fs.FS) error {
	if _, err := io.WriteString(w, Text); err != nil {
		return err
	}
	if app == nil {
		return nil
	}
	b, err := fs.ReadFile(app, AppFile)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	if _, err := io.WriteString(w, "\n"+separator+"\n\n"); err != nil {
		return err
	}
	_, err = w.Write(b)
	return err
}

const separator = "################################################################################"
